CREATE TABLE videos(id TEXT PRIMARY KEY,name TEXT NOT NULL,width INTEGER NOT NULL CHECK(width>0),height INTEGER NOT NULL CHECK(height>0),duration_seconds DOUBLE PRECISION NOT NULL CHECK(duration_seconds>0 AND duration_seconds<'Infinity'::float8),status TEXT NOT NULL CHECK(status='ready'),created_at TEXT NOT NULL,storage_key TEXT NOT NULL UNIQUE);
CREATE TABLE jobs(id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN ('extraction','import')),video_id TEXT REFERENCES videos(id),batch_id TEXT UNIQUE,status TEXT NOT NULL CHECK(status IN ('queued','running','cancelling','completed','failed','cancelled')),progress DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK(progress>=0 AND progress<=1),error TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,CHECK((kind='extraction' AND video_id IS NOT NULL AND batch_id IS NOT NULL) OR (kind='import' AND batch_id IS NULL)));
CREATE TABLE batches(id TEXT PRIMARY KEY,video_id TEXT NOT NULL REFERENCES videos(id),job_id TEXT NOT NULL UNIQUE REFERENCES jobs(id),created_at TEXT NOT NULL,UNIQUE(id,video_id));
CREATE TABLE frames(id TEXT PRIMARY KEY,video_id TEXT NOT NULL REFERENCES videos(id),batch_id TEXT NOT NULL,timestamp_ms BIGINT NOT NULL CHECK(timestamp_ms>=0),width INTEGER NOT NULL CHECK(width>0),height INTEGER NOT NULL CHECK(height>0),status TEXT NOT NULL DEFAULT 'not_started' CHECK(status IN ('not_started','in_progress','completed')),revision BIGINT NOT NULL DEFAULT 0 CHECK(revision>=0),storage_key TEXT NOT NULL UNIQUE,FOREIGN KEY(batch_id,video_id) REFERENCES batches(id,video_id),UNIQUE(batch_id,timestamp_ms));
CREATE TABLE annotations(id TEXT CONSTRAINT annotations_global_id PRIMARY KEY,frame_id TEXT NOT NULL REFERENCES frames(id) ON DELETE CASCADE,x DOUBLE PRECISION NOT NULL CHECK(x>=0 AND x<'Infinity'::float8),y DOUBLE PRECISION NOT NULL CHECK(y>=0 AND y<'Infinity'::float8),width DOUBLE PRECISION NOT NULL CHECK(width>0 AND width<'Infinity'::float8),height DOUBLE PRECISION NOT NULL CHECK(height>0 AND height<'Infinity'::float8),source TEXT NOT NULL CHECK(source='manual'));
CREATE INDEX frames_batch ON frames(batch_id,timestamp_ms);
CREATE INDEX annotations_frame ON annotations(frame_id);

